//! Geometry construction matching the C++ test generator.

/// Build the same polygon rings as the C++ `main` does for a given `n`.
///
/// Each ring `layer` contains `(layer + 3) * 2` points on a circle of
/// radius `(layer + 1) * 0.3`, shifted by `layer * 0.1`.
pub fn build_polygon(n: i32) -> Vec<Vec<[f64; 2]>> {
    let mut polygon = Vec::new();

    for layer in 0..n {
        let mut ring = Vec::new();
        let radius = (layer as f64 + 1.0) * 0.3;
        let count = ((layer + 3) * 2) as usize;
        let offset = layer as f64 * 0.1;

        for i in 0..count {
            let angle = 2.0 * std::f64::consts::PI * i as f64 / count as f64;
            ring.push([
                (radius + offset) * angle.cos(),
                (radius + offset) * angle.sin(),
            ]);
        }

        polygon.push(ring);
    }

    polygon
}

/// C `atoi`-compatible parsing for the single optional CLI argument.
///
/// Leading ASCII whitespace is skipped, one optional sign is accepted, and
/// parsing stops at the first non-digit. Non-numeric input becomes `0`.
pub fn atoi_like(s: &str) -> i32 {
    let bytes = s.as_bytes();
    let mut i = 0usize;

    while i < bytes.len() && matches!(bytes[i], b' ' | b'\t' | b'\n' | b'\r' | 0x0b | 0x0c) {
        i += 1;
    }

    let mut negative = false;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        negative = bytes[i] == b'-';
        i += 1;
    }

    let mut value: i32 = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        value = value
            .saturating_mul(10)
            .saturating_add((bytes[i] - b'0') as i32);
        i += 1;
    }

    if negative { -value } else { value }
}

