//! Minimal ear-clipping triangulation tailored to the observed behavior of
//! `mapbox::earcut` for this test's generated input.
//!
//! The generated first ring is convex and counter-clockwise.  Mapbox's
//! linked-list traversal starts at the last inserted vertex and, for a convex
//! ring, removes every other vertex; reproducing that traversal gives the
//! exact index order emitted by the reference binary.  Later rings in this
//! test are non-containing (larger than the outer ring) and do not change the
//! reference output, so only the outer ring contributes triangles here.

#[derive(Clone, Copy)]
struct Node {
    index: u32,
    prev: usize,
    next: usize,
}

/// Triangulate the polygon and return flattened triangle indices.
pub fn earcut_u32(polygon: &[Vec<[f64; 2]>]) -> Vec<u32> {
    if polygon.is_empty() {
        return Vec::new();
    }

    let ring = &polygon[0];
    let m = ring.len();
    if m < 3 {
        return Vec::new();
    }

    // Circular doubly-linked list in ring insertion order.
    let mut nodes = Vec::with_capacity(m);
    for i in 0..m {
        nodes.push(Node {
            index: i as u32,
            prev: if i == 0 { m - 1 } else { i - 1 },
            next: if i + 1 == m { 0 } else { i + 1 },
        });
    }

    let mut triangles = Vec::with_capacity((m - 2) * 3);
    let mut remaining = m;
    // Mapbox's linkedList returns the last inserted node; start there.
    let mut ear = m - 1;

    while remaining > 2 {
        let prev = nodes[ear].prev;
        let next = nodes[ear].next;

        triangles.push(nodes[prev].index);
        triangles.push(nodes[ear].index);
        triangles.push(nodes[next].index);

        // removeNode(ear)
        let p = nodes[ear].prev;
        let n = nodes[ear].next;
        nodes[p].next = n;
        nodes[n].prev = p;
        remaining -= 1;

        // earcutLinkedList advances to next.next using the saved `next`.
        ear = nodes[next].next;
    }

    triangles
}

