#[path = "src/earcut.rs"]
mod earcut;
#[path = "src/geometry.rs"]
mod geometry;

use std::io::{self, Write};

fn main() {
    let mut n = 10i32;
    let mut args = std::env::args();
    let _ = args.next(); // program name
    if let Some(arg) = args.next() {
        n = geometry::atoi_like(&arg);
    }

    let polygon = geometry::build_polygon(n);
    let indices = earcut::earcut_u32(&polygon);

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    for idx in indices {
        // Matches `std::cout << idx << " "` including the trailing space and
        // the absence of a final newline.
        let _ = write!(out, "{} ", idx);
    }
    let _ = out.flush();
}

